Given an array arr[] and an integer k, the task is to find k largest elements in the given array. Elements in the output array should be in decreasing order.Examples:Input:  [1, 23, 12, 9, 30, 2, 50], k = 3Output: [50, 30, 23]Input:  [11, 5, 12, 9, 44, 17, 2], k = 2Output: [44, 17]Try It YourselfTable of Content[Naive Approach] Using Sorting [Expected Approach] Using Priority Queue(Min-Heap)[Alternate Approach] Using Quick Select algorithm - O(n^2) in Worst[Naive Approach] Using Sorting The idea is to sort the input array in descending order, so the first k elements in the array will be the k largest elements.
            C++

    // C++ program to find k largest elements in an 
// array using sorting

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> kLargest(vector<int> &arr, int k) {

    // sort the given array in descending order
    sort(arr.begin(), arr.end(), greater<int>());

  	// store the first k element in result array
    vector<int> res(arr.begin(), arr.begin() + k);
  	return res;
}

int main() {
    vector<int>arr = {1, 23, 12, 9, 30, 2, 50};
    int k = 3;

    vector<int> res = kLargest(arr, k);
  	for(int ele : res)
      	cout << ele << " ";

  	return 0;
}


